-- Generated by pwc-to-dbt from PowerCenter mapping m_FL_JS_MARTS_CORE: target ORDERS (instance ORDERS).
-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SQ_STG_SUPPLIES2 -> AGG_SUPPLIES_BY_PRODUCT2 -> SQ_STG_ORDER_ITEMS1 -> SQ_STG_PRODUCTS2 -> JNR_ITEMS_PRODUCTS -> JNR_ITEMS_SUPPLIES -> AGG_ITEMS_BY_ORDER -> SQ_STG_ORDERS1 -> JNR_ORDERS_ITEMS_AGG -> EXP_ORDERS_CALC -> SRT_BY_CUSTOMER -> EXP_CUSTOMER_ORDER_NUM -> ORDERS
-- WARNING [EXP_CUSTOMER_ORDER_NUM]: comparison `customer_id = customer_id` compares a value with itself: always true unless NULL (check variable-port order in the source mapping)

with

sq_stg_supplies2 as (
    -- SQ_STG_SUPPLIES2 (Source Qualifier): reads STG_SUPPLIES
    select
        cast(supply_id as varchar) as supply_id,
        cast(supply_name as varchar) as supply_name,
        cast(supply_cost_cents as decimal(12, 2)) as supply_cost_cents,
        cast(supply_cost as decimal(12, 2)) as supply_cost,
        cast(is_perishable as decimal(1, 0)) as is_perishable,
        cast(product_id as varchar) as product_id
    from {{ ref('stg_supplies') }}
),

agg_supplies_by_product2 as (
    -- AGG_SUPPLIES_BY_PRODUCT2 (Aggregator) grouped by PRODUCT_ID
    select
        product_id as product_id,
        sum(supply_cost) as supply_cost_per_product
    from sq_stg_supplies2
    group by product_id
),

sq_stg_order_items1 as (
    -- SQ_STG_ORDER_ITEMS1 (Source Qualifier): reads STG_ORDER_ITEMS
    select
        cast(order_item_id as varchar) as order_item_id,
        cast(order_id as varchar) as order_id,
        cast(product_id as varchar) as product_id
    from {{ ref('stg_order_items') }}
),

sq_stg_products2 as (
    -- SQ_STG_PRODUCTS2 (Source Qualifier): reads STG_PRODUCTS
    select
        cast(product_id as varchar) as product_id,
        cast(product_name as varchar) as product_name,
        cast(product_type as varchar) as product_type,
        cast(product_price_cents as double) as product_price_cents,
        cast(product_price as decimal(12, 2)) as product_price,
        cast(product_description as varchar) as product_description,
        cast(is_food_item as decimal(1, 0)) as is_food_item,
        cast(is_drink_item as decimal(1, 0)) as is_drink_item
    from {{ ref('stg_products') }}
),

jnr_items_products as (
    -- JNR_ITEMS_PRODUCTS (Joiner, Normal Join): PRODUCT_ID1 = PRODUCT_ID
    select
        master.order_id as order_id,
        master.order_item_id as order_item_id,
        detail.product_id as product_id,
        detail.product_price as product_price,
        detail.is_food_item as is_food_item,
        detail.is_drink_item as is_drink_item
    from sq_stg_products2 as detail
    inner join sq_stg_order_items1 as master
        on (master.product_id = detail.product_id)
),

jnr_items_supplies as (
    -- JNR_ITEMS_SUPPLIES (Joiner, Master Outer Join): PRODUCT_ID = PRODUCT_ID1
    select
        master.order_id as order_id,
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        master.product_price as product_price,
        master.is_food_item as is_food_item,
        master.is_drink_item as is_drink_item,
        detail.supply_cost_per_product as supply_cost_per_product
    from agg_supplies_by_product2 as detail
    left join jnr_items_products as master
        on (master.product_id = detail.product_id)
),

agg_items_by_order as (
    -- AGG_ITEMS_BY_ORDER (Aggregator) grouped by ORDER_ID
    select
        order_id as order_id,
        count(*) as items_count,
        sum(product_price) as order_items_subtotal,
        sum(case when (supply_cost_per_product is null) then 0 else supply_cost_per_product end) as order_cost,
        max(is_food_item) as has_food_items,
        max(is_drink_item) as has_drink_items
    from jnr_items_supplies
    group by order_id
),

sq_stg_orders1 as (
    -- SQ_STG_ORDERS1 (Source Qualifier): reads STG_ORDERS
    select
        cast(order_id as varchar) as order_id,
        cast(customer_id as varchar) as customer_id,
        cast(location_id as varchar) as location_id,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(subtotal_cents as double) as subtotal_cents,
        cast(tax_paid_cents as double) as tax_paid_cents,
        cast(order_total_cents as decimal(12, 2)) as order_total_cents,
        cast(subtotal as double) as subtotal,
        cast(tax_paid as double) as tax_paid,
        cast(order_total as decimal(12, 2)) as order_total
    from {{ ref('stg_orders') }}
),

jnr_orders_items_agg as (
    -- JNR_ORDERS_ITEMS_AGG (Joiner, Master Outer Join): ORDER_ID1 = ORDER_ID
    select
        detail.order_id as order_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.subtotal_cents as subtotal_cents,
        master.tax_paid_cents as tax_paid_cents,
        master.order_total_cents as order_total_cents,
        master.subtotal as subtotal,
        master.tax_paid as tax_paid,
        master.order_total as order_total,
        detail.items_count as items_count,
        detail.order_items_subtotal as order_items_subtotal,
        detail.order_cost as order_cost,
        detail.has_food_items as has_food_items,
        detail.has_drink_items as has_drink_items
    from agg_items_by_order as detail
    left join sq_stg_orders1 as master
        on (master.order_id = detail.order_id)
),

exp_orders_calc as (
    -- EXP_ORDERS_CALC (Expression)
    select
        order_id as order_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        (subtotal_cents / 100) as subtotal_recal,
        (tax_paid_cents / 100) as tax_paid_recal,
        (order_total_cents / 100) as order_total_recal,
        case when (order_items_subtotal is null) then 0 else order_items_subtotal end as order_items_subtotal_cl,
        case when (order_cost is null) then 0 else order_cost end as order_cost_cl,
        case when (has_food_items is null) then 0 else has_food_items end as has_food_items_cl,
        case when (has_drink_items is null) then 0 else has_drink_items end as has_drink_items_cl
    from jnr_orders_items_agg
),

srt_by_customer as (
    -- SRT_BY_CUSTOMER (Sorter on customer_id asc, ordered_at_day asc, order_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        order_id as order_id,
        subtotal_recal as subtotal_recal,
        tax_paid_recal as tax_paid_recal,
        order_total_recal as order_total_recal,
        order_items_subtotal_cl as order_items_subtotal_cl,
        order_cost_cl as order_cost_cl,
        has_food_items_cl as has_food_items_cl,
        has_drink_items_cl as has_drink_items_cl
    from exp_orders_calc
),

exp_customer_order_num__rows as (
    -- EXP_CUSTOMER_ORDER_NUM (Expression) step 1: inputs and per-row parts of the self-referencing variables
    select
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        order_id as order_id,
        subtotal_recal as subtotal,
        tax_paid_recal as tax_paid,
        order_total_recal as order_total,
        order_items_subtotal_cl as order_items_subtotal,
        order_cost_cl as order_cost,
        has_food_items_cl as has_food_items,
        has_drink_items_cl as has_drink_items,
        not coalesce((customer_id = customer_id), false) as __v_order_sequence_reset,
        1 as __v_order_sequence_step,
        1 as __v_order_sequence_init
    from srt_by_customer
),

exp_customer_order_num__groups as (
    -- EXP_CUSTOMER_ORDER_NUM step 2: every reset row starts a new group
    select
        *,
        sum(case when __v_order_sequence_reset then 1 else 0 end) over (order by customer_id asc, ordered_at_day asc, order_id asc rows between unbounded preceding and current row) as __v_order_sequence_grp
    from exp_customer_order_num__rows
),

exp_customer_order_num__running as (
    -- EXP_CUSTOMER_ORDER_NUM step 3: running value of each counter within its group
    select
        *,
        sum(case when __v_order_sequence_reset then __v_order_sequence_init else __v_order_sequence_step end) over (partition by __v_order_sequence_grp order by customer_id asc, ordered_at_day asc, order_id asc rows between unbounded preceding and current row) as v_order_sequence
    from exp_customer_order_num__groups
),

exp_customer_order_num as (
    -- EXP_CUSTOMER_ORDER_NUM (Expression) outputs
    select
        order_id as order_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        subtotal as subtotal,
        tax_paid as tax_paid,
        order_total as order_total,
        order_items_subtotal as order_items_subtotal,
        order_cost as order_cost,
        has_food_items as has_food_items,
        has_drink_items as has_drink_items,
        v_order_sequence as customer_order_number
    from exp_customer_order_num__running
),

final as (
    -- ORDERS (Target ORDERS): cast to the target column types
    select
        cast(order_id as varchar) as order_id,
        cast(customer_id as varchar) as customer_id,
        cast(location_id as varchar) as location_id,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(subtotal as decimal(12, 2)) as subtotal,
        cast(tax_paid as decimal(12, 2)) as tax_paid,
        cast(order_total as decimal(12, 2)) as order_total,
        cast(order_items_subtotal as decimal(12, 2)) as order_items_subtotal,
        cast(order_cost as decimal(12, 2)) as order_cost,
        cast(has_food_items as decimal(1, 0)) as has_food_items,
        cast(has_drink_items as decimal(1, 0)) as has_drink_items,
        cast(customer_order_number as decimal(15, 0)) as customer_order_number
    from exp_customer_order_num
)

select * from final
